// Locator repairs may change getBy* calls only. Expected outcomes are frozen.
import { expect, test, type Page } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

const baseURL = process.env.TESTFORGE_BASE_URL ?? 'http://127.0.0.1:4173';

function openUrl(locale: 'en' | 'es') {
  const url = new URL(baseURL);
  url.searchParams.set('lang', locale);
  if (process.env.TESTFORGE_BUGS) url.searchParams.set('bugs', process.env.TESTFORGE_BUGS);
  if (process.env.TESTFORGE_ATTEMPT) url.searchParams.set('attempt', process.env.TESTFORGE_ATTEMPT);
  return url.toString();
}

async function submissionCount(page: Page) {
  const response = await page.request.get(new URL('/api/submissions', baseURL).toString());
  const body = (await response.json()) as unknown[];
  return body.length;
}

test.beforeEach(async ({ request }) => {
  const response = await request.delete(new URL('/api/submissions', baseURL).toString());
  expect(response.ok()).toBeTruthy();
});

test('English applicant submits a complete remote application', async ({ page }) => {
  // case:en-happy-path
  const locale = 'en' as const;
  await page.goto(openUrl(locale));
  await page.getByLabel('Full name', { exact: true }).fill('Jordan Lee');
  await page.getByLabel('Email', { exact: true }).fill('jordan.lee@northline.dev');
  await page.getByLabel('Phone', { exact: true }).fill('+1 415 555 0148');
  await page.getByLabel('Role', { exact: true }).selectOption('qa');
  await page.getByRole('radio', { name: 'Remote', exact: true }).check();
  await page.getByLabel('Timezone', { exact: true }).selectOption('America/Mexico_City');
  await page.getByLabel('Portfolio review', { exact: true }).selectOption('tue-10');
  await page.getByTestId('submit-application').click();
  await expect(page.getByTestId('confirmation-banner')).toContainText('Application received');
  await expect.poll(async () => submissionCount(page)).toBe(1);
});

